package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map.Entry;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveInputStream_matches_TriageGen0Test {

    private static final int MAGIC_OFFSET = TarConstants.MAGIC_OFFSET;
    private static final int MAGICLEN = TarConstants.MAGICLEN;
    private static final int VERSION_OFFSET = TarConstants.VERSION_OFFSET;
    private static final int VERSIONLEN = TarConstants.VERSIONLEN;
    private static final int MIN_REQUIRED_LENGTH = TarConstants.VERSION_OFFSET + TarConstants.VERSIONLEN;

    private byte[] createBuffer(String magic, String version) {
        byte[] buffer = new byte[Math.max(MIN_REQUIRED_LENGTH, 100)];
        byte[] magicBytes = magic.getBytes();
        byte[] versionBytes = version.getBytes();

        System.arraycopy(magicBytes, 0, buffer, MAGIC_OFFSET, Math.min(magicBytes.length, MAGICLEN));
        System.arraycopy(versionBytes, 0, buffer, VERSION_OFFSET, Math.min(versionBytes.length, VERSIONLEN));
        return buffer;
    }

    @Test
    public void testMatches_LengthTooShort() {
        byte[] signature = new byte[MIN_REQUIRED_LENGTH - 1];
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
        assertFalse(TarArchiveInputStream.matches(signature, MIN_REQUIRED_LENGTH - 1));
    }

    @Test
    public void testMatches_PosixSuccess() {
        byte[] signature = createBuffer(TarConstants.MAGIC_POSIX, TarConstants.VERSION_POSIX);
        assertTrue(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_PosixMagicMismatch() {
        byte[] signature = createBuffer("WRONG", TarConstants.VERSION_POSIX);
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_PosixVersionMismatch() {
        byte[] signature = createBuffer(TarConstants.MAGIC_POSIX, "WRONG");
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_GnuSpaceSuccess() {
        byte[] signature = createBuffer(TarConstants.MAGIC_GNU, TarConstants.VERSION_GNU_SPACE);
        assertTrue(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_GnuZeroSuccess() {
        byte[] signature = createBuffer(TarConstants.MAGIC_GNU, TarConstants.VERSION_GNU_ZERO);
        assertTrue(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_GnuMagicMismatch() {
        byte[] signature = createBuffer("WRONG", TarConstants.VERSION_GNU_SPACE);
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_GnuVersionMismatch() {
        byte[] signature = createBuffer(TarConstants.MAGIC_GNU, "WRONG");
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_AntSuccess() {
        byte[] signature = createBuffer(TarConstants.MAGIC_ANT, TarConstants.VERSION_ANT);
        assertTrue(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_AntMagicMismatch() {
        byte[] signature = createBuffer("WRONG", TarConstants.VERSION_ANT);
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_AntVersionMismatch() {
        byte[] signature = createBuffer(TarConstants.MAGIC_ANT, "WRONG");
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
    }

    @Test
    public void testMatches_NoMatch() {
        byte[] signature = createBuffer("NONE", "NONE");
        assertFalse(TarArchiveInputStream.matches(signature, signature.length));
    }
}
